WITH взято AS (SELECT c.name, c.compare, c.source_kind, c.source_name, c.copy_kind, c.copy_name, (SELECT (regexp_match(d.content, c.source_pattern))[1] FROM project_documents d WHERE d.project_id = c.project_id AND d.entity_kind = c.source_kind AND d.entity_name = c.source_name) AS у_источника, (SELECT (regexp_match(d.content, c.pattern))[1] FROM project_documents d WHERE d.project_id = c.project_id AND d.entity_kind = c.copy_kind AND d.entity_name = c.copy_name) AS у_копии FROM derived_copy c WHERE c.project_id = $1) SELECT в.name || ': источник ' || в.source_kind || ':' || в.source_name || ' говорит «' || coalesce(в.у_источника, '‹не нашлось›') || '», копия ' || в.copy_kind || ':' || в.copy_name || ' — «' || coalesce(в.у_копии, '‹не нашлось›') || '»' AS detail FROM взято в WHERE в.compare = 'count' AND в.у_источника IS DISTINCT FROM в.у_копии UNION ALL SELECT в.name || ': копия ' || в.copy_kind || ':' || в.copy_name || ' сверяется телом, а датчика для этого нет — мерить нечем, и это не «сходится»' FROM взято в WHERE в.compare = 'body' ORDER BY 1
